-- Tags: no-darwin
-- no-darwin: `long double` is `double` on arm64 macOS, so Float32 of a value with more than 53 significant bits is rounded twice there.

-- Bit patterns of wide integer and wide Decimal conversions to Float64 and Float32 around the 64-bit boundary.
-- Every value is either below 2^64 in magnitude or exact in Float64, so every platform with an x87 or binary128 `long double` agrees.

SELECT 'Int128', s, reinterpretAsUInt64(toFloat64(x)), reinterpretAsUInt32(toFloat32(x))
FROM (SELECT arrayJoin(['0', '1', '-1', '9007199254740993', '-9007199254740993', '1152921573326323712', '1152921573326323713',
    '-1152921573326323713', '9223372036854775807', '-9223372036854775808', '9223372036854775808', '-9223372036854775809',
    '18446744073709551615', '-18446744073709551611', '-18446744073709551615', '18446744073709551616', '-18446744073709551616',
    '18446744073709555712', '-18446744073709555712', '1267650600228229401496703205376', '-1267650600228229401496703205376',
    '-170141183460469231731687303715884105728']) AS s, toInt128(s) AS x);

SELECT 'Int256', s, reinterpretAsUInt64(toFloat64(x)), reinterpretAsUInt32(toFloat32(x))
FROM (SELECT arrayJoin(['0', '1', '-1', '9007199254740993', '-9007199254740993', '1152921573326323712', '1152921573326323713',
    '-1152921573326323713', '9223372036854775807', '-9223372036854775808', '9223372036854775808', '-9223372036854775809',
    '18446744073709551615', '-18446744073709551611', '-18446744073709551615', '18446744073709551616', '-18446744073709551616',
    '18446744073709555712', '-18446744073709555712', '1267650600228229401496703205376', '-1267650600228229401496703205376',
    '-170141183460469231731687303715884105728', '170141183460469212842221372237303250944', '170141183460469231731687303715884105728',
    '-170141183460469269510619166673045815296', '340282366920938463463374607431768211456', '-340282366920938463463374607431768211456',
    '6277101735386680763835789423207666416102355444464034512896',
    '-6277101735386680763835789423207666416102355444464034512896']) AS s, toInt256(s) AS x);

SELECT 'UInt128', s, reinterpretAsUInt64(toFloat64(x)), reinterpretAsUInt32(toFloat32(x))
FROM (SELECT arrayJoin(['0', '1', '9223372036854775807', '9223372036854775808', '9223372036854776832', '9223372036854776833',
    '9223372036854778880', '9223372586610589696', '9223372586610589697', '18446744073709551615', '18446744073709551616',
    '18446744073709555712', '1267650600228229401496703205376', '170141183460469231731687303715884105728']) AS s, toUInt128(s) AS x);

SELECT 'UInt256', s, reinterpretAsUInt64(toFloat64(x)), reinterpretAsUInt32(toFloat32(x))
FROM (SELECT arrayJoin(['0', '1', '9223372036854775807', '9223372036854775808', '9223372036854776832', '9223372036854776833',
    '9223372036854778880', '9223372586610589696', '9223372586610589697', '18446744073709551615', '18446744073709551616',
    '18446744073709555712', '1267650600228229401496703205376', '170141183460469231731687303715884105728',
    '340282366920938463463374607431768211456', '6277101735386680763835789423207666416102355444464034512896',
    '340365443670675020705431095373035732992', '6278634230927546652694147770234816725285974183586218115072']) AS s, toUInt256(s) AS x);

SELECT 'Decimal128(5)', s, reinterpretAsUInt64(toFloat64(d)), reinterpretAsUInt32(toFloat32(d)), reinterpretAsUInt64(d * 1.5)
FROM (SELECT arrayJoin(['-92233720368547.75808', '92233720368547.75808', '-0.00001', '1.5']) AS s, toDecimal128(s, 5) AS d);

SELECT 'Decimal256(10)', s, reinterpretAsUInt64(toFloat64(d)), reinterpretAsUInt32(toFloat32(d)), reinterpretAsUInt64(d * 1.5)
FROM (SELECT arrayJoin(['-922337203.6854775808', '922337203.6854775808', '-0.0000000001', '1.5']) AS s, toDecimal256(s, 10) AS d);
